 "Is there a refund policy?": "Existe política de reembolso?",
 "It applies only to products in these collections.": "Vale só para produtos destas coleções.",
 "It could not be published. Try again.": "Não foi possível publicar. Tente de novo.",
 "It disappears for everyone. Orders and payments are kept. Not possible while members still pay for it.": "Ela some para todos. Pedidos e pagamentos são mantidos. Não é possível enquanto houver membros pagando.",
 "It goes back to their card in 5 to 10 business days, and your share comes back from your Stripe balance. They get an email.": "Volta para o cartão em 5 a 10 dias úteis, e sua parte sai do seu saldo Stripe. A pessoa recebe um e-mail.",
 "It goes live at": "Vai ao ar em",
 "It has not been saved yet, so it will not be kept.": "Ele ainda não foi salvo, então não será mantido.",
 "It has not been saved yet, so nothing you added will be kept.": "Ele ainda não foi salvo, então nada do que você adicionou será mantido.",
 "It has to end after it starts.": "Precisa terminar depois de começar.",
 "It hides before it shows, so it would never be on the page.": "Ele some antes de aparecer, então nunca estaria na página.",
 "It is a draft. Only you can see it until you publish.": "É um rascunho. Só você vê até publicar.",
 "It is gone for good, with its photos. To take it off your store and keep it, hide it instead.": "Ela some para sempre, com as fotos. Para tirá-la da loja e mantê-la, oculte em vez disso.",
 "It is hidden from your product page and its rating now. Storelib reads it and either brings it back or keeps it hidden.": "Ela já está oculta na página do produto e na nota. O Storelib lê e a traz de volta ou mantém oculta.",
 "It is not a Storelib product and is not listed anywhere else.": "Não é um produto da Storelib e não aparece em nenhum outro lugar.",
 "It is not connected yet, so nothing stops working.": "Ainda não está conectado, então nada para de funcionar.",
 "It is off until you turn it on.": "Fica desativada até você ativar.",
 "It is removed from Messages. The email you got about it stays in your inbox, and the sender stays in your contacts.": "Ela sai de Mensagens. O e-mail que você recebeu sobre ela continua na sua caixa, e o remetente continua nos seus contatos.",
 "It is removed with its numbers. Anything already sent stays in people's inboxes.": "Ela é removida com os números. O que já foi enviado continua nas caixas de entrada.",
 "It is yours": "É seu",
 "It opens soon": "Abre em breve",
 "It plays on your page in the YouTube or Vimeo player.": "É reproduzido na sua página no player do YouTube ou Vimeo.",
 "It replaces “{name}” at": "Ele substitui “{name}” em",
 "It shows as cancelled to members, and anyone going hears about it. You can put it back on.": "Aparece como cancelado para os membros e quem ia é avisado. Você pode confirmar de novo.",
 "It starts as a draft. Add its lessons, then publish it.": "Começa como rascunho. Adicione as aulas e depois publique.",
 "It stops at once for everyone partway through, and its history goes with it.": "Ela para na hora para todos que estão no meio do caminho, e o histórico vai junto.",
 "It takes nothing off downloads or courses in the same cart.": "Não desconta nada de downloads ou cursos no mesmo carrinho.",
 "It usually arrives in 1 to 3 business days.": "Costuma chegar em 1 a 3 dias úteis.",
