 "It was deleted. The email you got about it is still in your inbox.": "Ela foi excluída. O e-mail que você recebeu sobre ela continua na sua caixa.",
 "It was used, or it's past the return window.": "Foi usado ou já passou do prazo de devolução.",
 "It's a passport": "É um passaporte",
