 "Members pay for a tier to join.": "Os membros pagam um nível para entrar.",
 "Members pay monthly or yearly to join your community.": "Os membros pagam por mês ou por ano para entrar na sua comunidade.",
 "Members pay once, in a checkout inside the community. ": "Os membros pagam uma vez, num checkout dentro da comunidade. ",
 "Members pay once, in a checkout inside the community. The meeting link, the address and who else is going open when they have a ticket.": "Os membros pagam uma vez, num checkout dentro da comunidade. O link da reunião, o endereço e quem mais vai aparecem quando eles têm ingresso.",
 "Members pay through Stripe. You can add a yearly price or more tiers later.": "Os membros pagam pela Stripe. Você pode adicionar um preço anual ou mais níveis depois.",
 "Members pay to join, every month, every year or once.": "Os membros pagam para entrar, por mês, por ano ou uma vez.",
 "Members pay you through Stripe. Nobody can join a paid community until payouts are connected.": "Os membros pagam você pela Stripe. Ninguém pode entrar numa comunidade paga até os repasses serem conectados.",
 "Members pay {amount} once, in a checkout inside the community. ": "Os membros pagam {amount} uma vez, num checkout dentro da comunidade. ",
 "Members pay {priceText}.": "Os membros pagam {priceText}.",
 "Members paying now, including anyone whose card is being retried. Somebody who cancelled keeps access until their period ends and is not counted.": "Membros pagando agora, incluindo quem está com o cartão em nova tentativa. Quem cancelou mantém o acesso até o fim do período e não é contado.",
 "Members post": "Membros publicam",
 "Members reach levels by taking part. Below it, they see the program with the level it opens at.": "Os membros chegam aos níveis participando. Abaixo dele, veem o programa com o nível em que abre.",
 "Members see it under Learn.": "Os membros veem em Aprender.",
 "Members see posts on their membership page. Put the membership on sale in Settings to let people join.": "Os membros veem as publicações na página da assinatura. Coloque a assinatura à venda em Configurações para as pessoas entrarem.",
 "Members see them before they join and when they post.": "Os membros veem antes de entrar e ao publicar.",
 "Members stop seeing it here. The course and its buyers are not touched.": "Os membros deixam de ver aqui. O curso e seus compradores não são afetados.",
 "Members stop seeing it in the classroom. The course and its buyers are not touched.": "Os membros deixam de ver na sala de aula. O curso e seus compradores não são afetados.",
 "Members stop seeing it, and every open report about it is closed. You can restore it from the Feed.": "Os membros deixam de ver e todas as denúncias abertas sobre isso são encerradas. Você pode restaurar no Feed.",
 "Members stop seeing it. You can restore it from Removed.": "Os membros deixam de ver. Você pode restaurar em Removidas.",
 "Members who could attend can watch it on the event page afterwards.": "Os membros que podiam participar podem assistir depois na página do evento.",
 "Members who have it lose it.": "Os membros que têm o selo perdem.",
 "Members write to you from the community. Messages reach your inbox and this email; it stays private unless you show it.": "Os membros escrevem para você pela comunidade. As mensagens chegam na sua caixa e neste e-mail; ele fica privado a menos que você mostre.",
