 "There is no space to post in. Add one under Spaces.": "Não há espaço para publicar. Adicione um em Espaços.",
 "There is nothing available to cash out yet.": "Ainda não há nada disponível para sacar.",
 "There were no paying members at the start of this period, so there is no rate yet.": "Não havia membros pagantes no início deste período, então ainda não há taxa.",
 "These photos are too large together. Send fewer, or smaller ones.": "Estas fotos são grandes demais juntas. Envie menos ou menores.",
 "These products have no weight saved: weigh the parcel.": "Estes produtos não têm peso salvo: pese o pacote.",
 "These will appear on your OnePage": "Elas vão aparecer na sua OnePage",
 "They are off for now. You can turn them on in": "Elas estão desativadas por enquanto. Você pode ativar em",
 "They are real starter projects rather than presets, and they come after the editor. Start blank or with AI for now.": "São projetos iniciais de verdade, não predefinições, e chegam depois do editor. Por enquanto comece do zero ou com IA.",
 "They are removed from your files, and anything that still shows one of them will show nothing.": "Eles são removidos dos seus arquivos, e onde ainda aparecerem não vai mostrar nada.",
 "They are unsubscribed and get no more of your emails.": "A pessoa é descadastrada e não recebe mais seus e-mails.",
 "They can ask again later.": "Pode pedir de novo depois.",
 "They can open the community and post again, and keep their points, level and posts.{free}": "Pode abrir a comunidade e publicar de novo, mantendo pontos, nível e publicações.{free}",
 "They can read everything but cannot post, comment, react or chat until it ends.": "Pode ler tudo, mas não pode publicar, comentar, reagir nem conversar até terminar.",
 "They can't place an order until they click the link we email them when they sign up. Turns on sign in as well.": "Eles só podem fazer pedidos depois de clicar no link que enviamos no cadastro. Também ativa o login.",
 "They get access again now, and keep their points, level and posts.{free}": "Recupera o acesso agora e mantém pontos, nível e publicações.{free}",
 "They get in without paying, and they are told what the ticket would have cost.": "Eles entram sem pagar e ficam sabendo quanto o ingresso custaria.",
 "They get this tier without paying, until you end it.": "Ganha este nível sem pagar até você encerrar.",
 "They have {points} now. ": "Tem {points} agora. ",
 "They hold the stock and ship it.": "Eles têm o estoque e enviam.",
 "They lose access and cannot join again unless you unban them.": "Perde o acesso e não pode entrar de novo, a menos que você desbana.",
 "They lose access now and can join again. A paid membership keeps billing until they cancel it.": "Perde o acesso agora e pode entrar de novo. Uma assinatura paga continua sendo cobrada até ser cancelada.",
 "They lose access until you bring them back. Their posts stay.": "Perde o acesso até você trazer de volta. As publicações ficam.",
